 public static function followupTask(int $id):int{if(!module_enabled('Planner'))throw new InvalidArgumentException(t('Enable Planner.'));$r=self::get('followups',$id);return Db::tx(function()use($id,$r){$old=Db::one('SELECT task_id FROM life_followup_tasks WHERE followup_id=? AND due_on=?',[$id,$r['due_on']]);if($old)return (int)$old['task_id'];$person=self::get('contacts',$r['contact_id']);$task=PlannerService::saveTask(null,['title'=>mb_substr('Follow up: '.$person['name'].' — '.$r['note'],0,200),'due'=>$r['due_on']]);Db::run('INSERT INTO life_followup_tasks(followup_id,due_on,task_id) VALUES(?,?,?)',[$id,$r['due_on'],$task]);return $task;});}
 public static function tick():array{$created=0;foreach(self::rows('followups')as $r)if($r['status']==='open'&&$r['auto_task']&&$r['due_on']<=date('Y-m-d')&&!Db::one('SELECT task_id FROM life_followup_tasks WHERE followup_id=? AND due_on=?',[$r['id'],$r['due_on']])){self::followupTask((int)$r['id']);$created++;}return ['tasks_created'=>$created];}
