 public static function definition(string $kind):array{return self::catalog()[$kind]??throw new InvalidArgumentException(t('Choose a life planning page.'));}
 public static function rows(string $kind):array{[$table]=self::definition($kind);return Db::all('SELECT t.* FROM '.$table.' t WHERE NOT EXISTS(SELECT 1 FROM life_archives a WHERE a.entity=? AND a.row_id=t.id) ORDER BY t.id DESC',[$kind]);}
 public static function get(string $kind,int $id):array{[$table]=self::definition($kind);$r=Db::one('SELECT * FROM '.$table.' WHERE id=?',[$id]);if(!$r||Db::one('SELECT row_id FROM life_archives WHERE entity=? AND row_id=?',[$kind,$id]))throw new InvalidArgumentException(t('Record not found.'));return $r;}
 public static function save(string $kind,array $input,?int $id=null,bool $transaction=true):int{
  if($transaction)return Db::tx(fn()=>self::save($kind,$input,$id,false));
  [$table,,$fields]=self::definition($kind);$old=$id===null?null:self::get($kind,$id);$d=[];$defaults=['actual_amount'=>'0','done'=>'0','status'=>'paid','purity_unit'=>'percent','purity'=>'100','compounding'=>'simple','tax_percent'=>'0','fees'=>'0','actual_cost'=>'0','bought'=>'0','interval_days'=>'0'];
  if($kind==='wishlist')$defaults['status']='open';$defaults['auto_task']='0';
  foreach($fields as $f=>$spec){$optional=str_starts_with($spec,'?');$type=ltrim($spec,'?');$v=$input[$f]??($old[$f]??($defaults[$f]??''));if(!is_scalar($v)||is_bool($v)||str_contains((string)$v,"\0"))throw new InvalidArgumentException(t('Check ').$f.'.');$v=trim((string)$v);if(mb_strlen($v)>2000)throw new InvalidArgumentException(t('Keep ').$f.' within 2000 characters.');if($v===''){if(!$optional)throw new InvalidArgumentException(t('Enter ').$f.'.');$d[$f]=in_array($type,['date','decimal'],true)||str_starts_with($type,'int:')?null:'';continue;}
   if($type==='date')valid_date($v);elseif($type==='month')valid_month($v);elseif($type==='money'||$type==='money0')$v=cents($v,$type==='money0')/100;elseif($type==='decimal'){if(!preg_match('/^\d{1,8}(?:\.\d{1,4})?$/D',$v))throw new InvalidArgumentException(t('Enter a non-negative decimal for ').$f.'.');$v=(float)$v;}elseif(str_starts_with($type,'int:')){[,$min,$max]=explode(':',$type);$v=int_range($v,(int)$min,(int)$max);}elseif(str_starts_with($type,'enum:')){if(!in_array($v,explode(',',substr($type,5)),true))throw new InvalidArgumentException(t('Choose a valid ').$f.'.');}elseif(str_starts_with($type,'ref:')){$v=record_id($v);self::get(substr($type,4),$v);}elseif($type==='currency'){$v=strtoupper($v);if(!preg_match('/^[A-Z]{3}$/D',$v))throw new InvalidArgumentException(t('Use a three-letter currency code.'));}$d[$f]=$v;
  }
  $d=self::validate($kind,$d,$old);$cols=array_keys($d);if($id===null)return Db::run('INSERT INTO '.$table.'('.implode(',',$cols).') VALUES('.implode(',',array_fill(0,count($cols),'?')).')',array_values($d));Db::run('UPDATE '.$table.' SET '.implode(',',array_map(fn($c)=>$c.'=?',$cols)).' WHERE id=?',[...array_values($d),$id]);return $id;
 }
 private static function validate(string $kind,array $d,?array $old):array{
  $unique=match($kind){'members'=>['seettu_id','round_no'],'seettu_payments'=>['seettu_id','round_no'],'member_payments'=>['member_id','round_no'],'payouts'=>['seettu_id','round_no'],'rates'=>['code','as_of'],'food_budgets'=>['month'],default=>[]};if($unique){[$table]=self::definition($kind);$where=implode(' AND ',array_map(fn($f)=>$f.'=?',$unique));$values=array_map(fn($f)=>$d[$f],$unique);$existing=Db::one('SELECT id FROM '.$table.' WHERE '.$where.' AND id<>?',[...$values,$old['id']??0]);if($existing)throw new InvalidArgumentException(t('An entry already exists for this period/round. Edit that entry instead.'));}
  if($kind==='items'&&$d['actual_amount']>0&&$d['actual_on']===null)throw new InvalidArgumentException(t('Enter the date of actual spending.'));
  if($kind==='groceries'&&$d['bought']==='1'&&$d['purchased_on']===null)throw new InvalidArgumentException(t('Enter the purchase date for bought groceries.'));
  if($kind==='reminders')$d['anchor_day']=$old&&$old['next_on']===$d['next_on']&&!empty($old['anchor_day'])?$old['anchor_day']:(int)substr($d['next_on'],8,2);
  foreach([['start_on','end_on'],['start_on','maturity_on'],['departs_on','returns_on']]as [$a,$b])if(isset($d[$a],$d[$b])&&$d[$a]>$d[$b])throw new InvalidArgumentException(t('End date must follow the start date.'));
  if(isset($d['weight'])&&$d['weight']<=0||isset($d['quantity'])&&$d['quantity']<=0)throw new InvalidArgumentException(t('Weight and quantity must be positive.'));
  if(isset($d['round_no'])){$circle=isset($d['seettu_id'])?self::get('seettu',$d['seettu_id']):self::get('seettu',self::get('members',$d['member_id'])['seettu_id']);if($d['round_no']>$circle['rounds'])throw new InvalidArgumentException(t('Round exceeds the circle\'s configured rounds.'));}
  if($kind==='payouts'){$member=self::get('members',$d['member_id']);if($member['seettu_id']!==$d['seettu_id']||$member['round_no']!==$d['round_no'])throw new InvalidArgumentException(t('Recipient must belong to this circle and round.'));}
  if($kind==='metals'&&$d['purity']!==null&&($d['purity']<=0||$d['purity']>($d['purity_unit']==='karat'?24:100)))throw new InvalidArgumentException(t('Check purity against its selected unit.'));
  if($kind==='prices'&&($d['purity']<=0||$d['purity']>100))throw new InvalidArgumentException(t('Price purity is a percentage from above zero to 100.'));
  if($kind==='deposits'){if($d['rate']>1000||$d['tax_percent']>100)throw new InvalidArgumentException(t('Check entered interest and tax rates.'));LifeFinanceMath::deposit($d);}
  if($kind==='loans')LifeFinanceMath::amortization($d['principal'],$d['annual_rate'],$d['months'],$d['early_month'],$d['early_amount'],$d['settlement_fee']);
  if($kind==='debts'&&$d['annual_rate']>1000)throw new InvalidArgumentException(t('Check the debt annual rate.'));
  if($kind==='rates'&&$d['rate_lkr']<=0)throw new InvalidArgumentException(t('Exchange rate must be positive.'));
  if($kind==='fx'){$rate=self::get('rates',$d['rate_id']);if($rate['as_of']>$d['date'])throw new InvalidArgumentException(t('Transaction cannot use a future exchange rate.'));$d['code']=$rate['code'];$d['rate_lkr']=$old&&$old['rate_id']===$d['rate_id']?$old['rate_lkr']:$rate['rate_lkr'];$d['source']=$old&&$old['rate_id']===$d['rate_id']?$old['source']:$rate['source'];$d['lkr_amount']=round($d['amount']*$d['rate_lkr'],2);if($d['lkr_amount']>1e10)throw new InvalidArgumentException(t('Converted amount exceeds the supported limit.'));}
  if($kind==='wishlist'){$added=$old['added_on']??date('Y-m-d');$minimum=date('Y-m-d',strtotime($added.' +30 days'));if($d['revisit_on']<$minimum)throw new InvalidArgumentException(t('Wishlist cooling-off must last at least 30 days from capture.'));if($d['status']==='bought'&&date('Y-m-d')<max($minimum,$d['revisit_on']))throw new InvalidArgumentException(t('Review this item after its cooling-off date before marking bought.'));$d['added_on']=$added;}
  if(in_array($kind,['items','groceries'],true)&&!empty($old['expense_id'])){$field=$kind==='items'?'actual_amount':'actual_cost';if((float)$old[$field]!==$d[$field])throw new InvalidArgumentException(t('Reverse the linked Money expense before changing the recorded cost.'));}
  return $d;
 }
 public static function archive(string $kind,int $id):void{$row=self::get($kind,$id);if(!empty($row['expense_id']))throw new InvalidArgumentException(t('Reverse its linked expense first.'));foreach(self::catalog()as $other=>[,, $fields])foreach($fields as $field=>$type)if($type==='ref:'.$kind)foreach(self::rows($other)as $r)if((int)$r[$field]===$id)throw new InvalidArgumentException(t('Archive linked ').$other.' records first.');Db::run('INSERT OR IGNORE INTO life_archives(entity,row_id) VALUES(?,?)',[$kind,$id]);}
 public static function recordExpense(string $kind,int $id,int $account,int $category,string $date):void{
  if(!in_array($kind,['items','groceries'],true)||!module_enabled('Salary'))throw new InvalidArgumentException(t('Enable Money and select a spending entry.'));$r=self::get($kind,$id);$amount=$r[$kind==='items'?'actual_amount':'actual_cost'];if($r['expense_id']||$amount<=0)throw new InvalidArgumentException(t('Enter a positive actual cost; an existing linked expense cannot be posted twice.'));[$table]=self::definition($kind);SalaryService::addExpense($date,$category,$account,(string)$amount,'Life planning: '.($r['title']??$r['item']),function($expense)use($kind,$id,$table,$amount){$fresh=self::get($kind,$id);if($fresh['expense_id']||(float)$fresh[$kind==='items'?'actual_amount':'actual_cost']!==(float)$amount)throw new InvalidArgumentException(t('Already posted.'));Db::run('UPDATE '.$table.' SET expense_id=? WHERE id=?',[$expense,$id]);});
 }
 public static function complete(string $kind,int $id,string $expected):void{
  if(!in_array($kind,['reminders','followups'],true))throw new InvalidArgumentException(t('Choose a recurring item.'));$r=self::get($kind,$id);$field=$kind==='reminders'?'next_on':'due_on';if($r['status']!=='active'&&$kind==='reminders'||$kind==='followups'&&$r['status']!=='open'||$r[$field]!==$expected)throw new InvalidArgumentException(t('This reminder changed or was already completed.'));
  Db::tx(function()use($r,$field,$kind,$id,$expected){$r=self::get($kind,$id);if($r[$field]!==$expected)throw new InvalidArgumentException(t('Occurrence already changed.'));$history=$kind==='reminders'?'life_health_completions':'life_followup_history';$link=$kind==='reminders'?'reminder_id':'followup_id';Db::run('INSERT INTO '.$history.'('.$link.',due_on,completed_on) VALUES(?,?,?)',[$id,$expected,date('Y-m-d')]);$next=null;if($kind==='reminders'&&$r['frequency']!=='once'){$date=new DateTimeImmutable($r[$field]);if($r['frequency']==='monthly'){$first=$date->modify('first day of next month');$next=$first->setDate((int)$first->format('Y'),(int)$first->format('m'),min((int)($r['anchor_day']??$date->format('d')),(int)$first->format('t')))->format('Y-m-d');}else $next=$date->modify($r['frequency']==='daily'?'+1 day':'+7 days')->format('Y-m-d');}elseif($kind==='followups'&&$r['interval_days']>0)$next=date('Y-m-d',strtotime($r[$field].' +'.$r['interval_days'].' days'));[$table]=self::definition($kind);if($next)Db::run('UPDATE '.$table.' SET '.$field.'=? WHERE id=?',[$next,$id]);else Db::run("UPDATE ".$table." SET status='done' WHERE id=?",[$id]);});
 }
 public static function groceryFromIngredient(int $id):void{Db::tx(function()use($id){$r=self::get('ingredients',$id);if($r['grocery_id'])throw new InvalidArgumentException(t('Ingredient already added to groceries.'));$idG=self::save('groceries',['item'=>$r['item'],'quantity'=>(string)$r['quantity'],'unit'=>$r['unit'],'estimated_cost'=>(string)$r['estimated_cost'],'actual_cost'=>'0','bought'=>'0','needed_on'=>self::get('meals',$r['meal_id'])['meal_date']],null,false);Db::run('UPDATE life_meal_ingredients SET grocery_id=? WHERE id=?',[$idG,$id]);});}
 public static function calendar(string $kind,int $id):void{if(!in_array($kind,['plans','trips'],true))throw new InvalidArgumentException(t('Choose a plan or trip.'));$r=self::get($kind,$id);if($r['appointment_id'])throw new InvalidArgumentException(t('A calendar appointment is already linked.'));$start=($r['start_on']??$r['departs_on']).' 09:00';$end=($r['end_on']??$r['returns_on']).' 17:00';[$table]=self::definition($kind);Db::tx(function()use($r,$start,$end,$table,$id,$kind){if(self::get($kind,$id)!==$r)throw new InvalidArgumentException(t('Plan changed; review it before linking.'));$appointment=Db::run("INSERT INTO planner_appointments(title,starts_at,ends_at,status,reminder_minutes) VALUES(?,?,?,'scheduled',60)",[$r['title']??$r['destination'],$start,$end]);Db::run('UPDATE '.$table.' SET appointment_id=? WHERE id=?',[$appointment,$id]);});}
}
